const labels={SAFE_EXECUTION:'Safe execution',UNSAFE_EXECUTION:'Unsafe execution',SAFE_BLOCK:'Safe block',INDETERMINATE:'Indeterminate',INVALID_SCENARIO:'Invalid scenario'};
const nav=[['home','Home','Investigation workspace'],['file','Workflows','Extract, review & correct'],['flow','Investigations','Model activity & findings'],['network','Counterfactuals','Test a condition change'],['shield','Safeguards','Verify execution gates'],['layers','Evidence','Source excerpts & provenance'],['list','Benchmark','Locked synthetic cases'],['certificate','Certificates','Export & verify integrity'],['cog','Settings','Models & request states']];
function Status({value,small=false}){const state=value==='UNSAFE_EXECUTION'||value==='VIOLATED'||value==='MISSING'?'bad':value==='UNKNOWN'||value==='INDETERMINATE'||value==='INVALID_SCENARIO'?'unknown':'good';return <span className={`status ${state} ${small?'small':''}`}><Icon name={state==='good'?'check':state==='bad'?'minus':'warning'} size={small?10:17}/>{!small&&(labels[value]??value?.replaceAll('_',' ').toLowerCase())}</span>;}
