 useEffect(()=>{if(wizard)dialogRef.current?.showModal();else dialogRef.current?.close();},[wizard]);
 useEffect(()=>{if(!drawer)return;const previous=document.activeElement;const panel=drawerRef.current;const focusable=()=>[...panel.querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')];focusable()[0]?.focus();const trap=e=>{if(e.key!=='Tab')return;const list=focusable(),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}};panel.addEventListener('keydown',trap);return()=>{panel.removeEventListener('keydown',trap);previous?.focus();};},[drawer]);
 useEffect(()=>{if(!notifications)return;const previous=document.activeElement;notificationRef.current?.querySelector('button')?.focus();return()=>previous?.focus();},[notifications]);
 useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(''),4000);return()=>clearTimeout(id);},[toast]);
 useEffect(()=>{const key=e=>{if(e.key==='Escape'){setDrawer(null);setMenu(false);setNotifications(false);} };document.addEventListener('keydown',key);return()=>document.removeEventListener('keydown',key);},[]);
 async function run(label,action){setToast(label);setError('');try{return await action();}catch(e){setError(e.message);}}
 function cancel(){state.cancel();setToast('Request cancelled. Completed results are preserved.');}
 async function resetFor(next){const response=await state.selectWorkflow(next);if(!response)return;setInspection(null);setCertCheck(null);setReviewed(false);setReplay(0);return response;}
