 function navigate(name){if(name!==view)addHistory('View opened',name);setView(name);setTab(name==='Workflows'?'Workflow review':name==='Evidence'?'Source evidence':name==='Home'?'Policy posture':'');setMenu(false);setDrawer(null);setError('');}
