 async function counterfactual(){const c=workflow.conditions.find(c=>c.id===condition);if(!c){setError('Select a condition.');return;}const value=replacement==='null'?null:c.valueType==='BOOLEAN'?replacement==='true':c.valueType==='NUMBER'?Number(replacement):replacement;const next={id:newId(),targetConditionId:c.id,originalValue:c.observedValue,replacementValue:value,reason:'Operator counterfactual',proposedBy:'USER',validated:true};const response=await state.applyIntervention(next);if(response){setReplay(0);addHistory('Counterfactual evaluated',response.result.outcome);}}
