 async function exportCert(){setCertCheck(null);const response=await state.exportCertificate();if(response){setCertCheck(await verifyCertificate(response,workflow));addHistory('Certificate exported',response.integrityHash.slice(0,12));}}
 function editObservation(id,value){const next={...workflow,conditions:workflow.conditions.map(c=>c.id===id?{...c,observedValue:value==='null'||c.valueType==='NUMBER'&&value===''?null:c.valueType==='BOOLEAN'?value==='true':c.valueType==='NUMBER'?Number(value):value}:c)};resetFor(next);setReviewed(false);}
 function toggleGate(id,stepId=workflow.steps[0]?.id){resetFor({...workflow,steps:workflow.steps.map(s=>s.id===stepId?{...s,executionGateIds:s.executionGateIds.includes(id)?s.executionGateIds.filter(c=>c!==id):[...s.executionGateIds,id]}:s)});setReviewed(false);}
 async function correctEvidence(id,excerpt){const entity=workflow.conditions.find(item=>item.id===id),doc=workflow.sourceDocuments[0],start=doc?.text.indexOf(excerpt)??-1;if(!entity||start<0||!excerpt){setError('Evidence must be a nonempty, exact excerpt of the source.');return;}const response=await resetFor({...workflow,conditions:workflow.conditions.map(c=>c.id===id?{...c,sourceSpans:[{sourceId:doc.id,startOffset:start,endOffset:start+excerpt.length,excerpt,verified:true}]}:c)});if(response){setSelected(response.workflow.conditions.find(item=>item.id===id));setToast('Evidence excerpt validated and updated.');}}

 const gaps=scene.policyRules.flatMap(r=>r.requiredConditionIds.filter(id=>!scene.steps.find(s=>s.id===r.subjectStepId)?.executionGateIds.includes(id)));
 const savedRecords=[...library.map(item=>({...item,workflow:sessionWorkflows.find(saved=>saved.id===item.id)??item.workflow})),...sessionWorkflows.filter(saved=>!library.some(item=>item.id===saved.id)).map(workflow=>({id:workflow.id,workflow}))];
 const records=savedRecords.some(item=>item.id===workflow.id)?savedRecords.map(item=>item.id===workflow.id?{...item,workflow}:item):[...savedRecords,{id:workflow.id,workflow}];
 const originalGaps=workflow.policyRules.flatMap(rule=>rule.requiredConditionIds.filter(id=>!workflow.steps.find(step=>step.id===rule.subjectStepId)?.executionGateIds.includes(id)));
 const metricWorkflow=view==='Workflows'?workflow:scene;
 const metricGaps=view==='Workflows'?originalGaps:gaps;
 const filtered=records.filter(x=>(scope!=='Selected workflow'||x.workflow.id===workflow.id)&&x.workflow.title.toLowerCase().includes(query.toLowerCase()));
 const spans=[...workflow.conditions,...workflow.policyRules,...workflow.steps].flatMap(e=>e.sourceSpans.map((s,i)=>({...s,entity:e.name??e.description,entityId:e.id,key:e.id+i})));
 const conditionState=c=>{if(!c||result?.unknownConditions.includes(c.id))return 'UNKNOWN';const value=scenario!=='BASELINE'&&change?.targetConditionId===c.id?change.replacementValue:c.observedValue;return value===null?'UNKNOWN':value===c.expectedValue?'SATISFIED':'VIOLATED';};
 const primary=scene.steps[0];
