 const metric=[['Workflows',records.length],['Conditions',workflow.conditions.length],['Missing gates',metricGaps.length],['Policies',workflow.policyRules.length],['Source excerpts',spans.length],['Execution gates',metricWorkflow.steps.reduce((a,s)=>a+s.executionGateIds.length,0)],['Dependencies',metricWorkflow.steps.reduce((a,s)=>a+s.dependsOn.length,0)],['Runs',history.filter(h=>h.action.includes('evaluated')||h.action.includes('tested')).length],['Completed model calls',state.modelCallCount],['Unknown',result?.unknownConditions.length??0],['Verified',verification?.resolved?1:0]];
